//! 🖊️ Drawing node ownership, explicit path geometries, colors, layers and styles.
use crate::standards::v1::subsets::base::schema::snapshot::sqlite::native::Bound;
use semio_framework_os_kernel::sqlite_snapshot::artifact::{FloatColumn,FloatRow as SqliteRow,insert_ieee754,insert_key_ieee754};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding::Owned;
use super::{SemioDrawingSnapshot,DrawCanvas,DrawStyle,DrawLayer,DrawNode,PathSegment,SemioPoint2,SemioPoint3,SemioQuaternion,SemioRgba,SemioTransform};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,Reconstruction},validate_sqlite_database_schema,SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase}};
use std::collections::{BTreeMap,BTreeSet};
fn number(n:usize)->Result<i64,String>{i64::try_from(n).map_err(|e|e.to_string())}
fn identity<'a>(r:impl std::borrow::Borrow<SqliteRow<'a>>,n:usize)->Result<(),String>{let r=*r.borrow();if r.rowid<=0||r.integer(0)?!=r.rowid||r.values.len()!=n{Err("invalid drawing row identity or columns".into())}else{Ok(())}}
fn boolean(n:i64)->Result<bool,String>{match n{0=>Ok(false),1=>Ok(true),_=>Err("invalid drawing boolean".into())}}
fn optional_real(r:SqliteRow<'_>,i:usize)->Result<Option<f64>,String>{if r.is_null(i)?{Ok(None)}else{r.real(i).map(Some)}}
fn rgba(r:SqliteRow<'_>,i:usize)->Result<Option<SemioRgba>,String>{let mut nulls=0;for channel in i..i+4{if r.is_null(channel)?{nulls+=1;}}if nulls==4{Ok(None)}else if nulls!=0{Err("drawing color channels must all be present or absent".into())}else{Ok(Some(SemioRgba{r:r.binary32(i)?,g:r.binary32(i+1)?,b:r.binary32(i+2)?,a:r.binary32(i+3)?}))}}
fn colors(color:Option<SemioRgba>)->[Cell<'static>;4]{match color{None=>[Cell::Null;4],Some(c)=>[Cell::Float32(c.r),Cell::Float32(c.g),Cell::Float32(c.b),Cell::Float32(c.a)]}}
fn point(r:SqliteRow<'_>,i:usize)->Result<SemioPoint2,String>{Ok(SemioPoint2{x:r.real(i)?,y:r.real(i+1)?})}
fn transform(r:SqliteRow<'_>)->Result<SemioTransform,String>{Ok(SemioTransform{translation:SemioPoint3{x:r.real(1)?,y:r.real(2)?,z:r.real(3)?},rotation:SemioQuaternion{x:r.real(4)?,y:r.real(5)?,z:r.real(6)?,w:r.real(7)?},scale:SemioPoint3{x:r.real(8)?,y:r.real(9)?,z:r.real(10)?}})}
fn details<'a>(db:&'a SqliteDatabase,name:&str,n:usize,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,SqliteRow<'a>>,String>{let mut rows=BTreeMap::new();for(count,r)in float_rows(db,name,c)?.into_iter().enumerate(){identity(r,n)?;if rows.insert(r.rowid,r).is_some(){return Err("duplicate drawing identity".into());}if count%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(rows)}
fn groups<'a>(db:&'a SqliteDatabase,name:&str,n:usize,parents:&BTreeMap<i64,SqliteRow<'_>>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<SqliteRow<'a>>>,String>{let mut result=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();for r in details(db,name,n,c)?.into_values(){if !parents.contains_key(&r.integer(1)?){return Err("dangling drawing relationship owner".into());}r.integer(2)?;result.entry(r.integer(1)?).or_default().push(r);}for rows in result.values_mut(){rows.sort_by_key(|r|r.integer(2).unwrap_or(-1));for(ordinal,r)in rows.iter().enumerate(){if r.integer(2)?!=number(ordinal)?{return Err("drawing relationship order must be contiguous".into());}}}Ok(result)}
fn style_cell<'a>(style:Option<&str>,names:&BTreeMap<&str,i64>)->Result<Cell<'a>,String>{style.map(|s|names.get(s).copied().map(Cell::Integer).ok_or_else(||String::from("dangling drawing style"))).transpose().map(|s|s.unwrap_or(Cell::Null))}
fn project_node(node:&DrawNode,styles:&BTreeMap<&str,i64>,p:&mut Projection<'_,'_>)->Result<i64,String>{let root=p.insert_float("semio_drawing_node",&[Cell::Text(match node{DrawNode::Path{..}=>"path",DrawNode::Text{..}=>"text",DrawNode::Group{..}=>"group",DrawNode::Image{..}=>"image"})])?;let mut stack=vec![(root,node)];while let Some((id,node))=stack.pop(){match node{
DrawNode::Path{segments,style}=>{p.insert_key_float("semio_drawing_path",id,&[style_cell(style.as_deref(),styles)?])?;for(ordinal,s)in segments.iter().enumerate(){let kind=match s{PathSegment::MoveTo{..}=>"move",PathSegment::LineTo{..}=>"line",PathSegment::CubicTo{..}=>"cubic",PathSegment::QuadTo{..}=>"quad",PathSegment::ArcTo{..}=>"arc",PathSegment::Close=>"close"};let sid=p.insert_float("semio_drawing_segment",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Text(kind)])?;match s{PathSegment::MoveTo{to}=>p.insert_key_float("semio_drawing_move",sid,&[Cell::Real(to.x),Cell::Real(to.y)])?,PathSegment::LineTo{to}=>p.insert_key_float("semio_drawing_line",sid,&[Cell::Real(to.x),Cell::Real(to.y)])?,PathSegment::CubicTo{c1,c2,to}=>p.insert_key_float("semio_drawing_cubic",sid,&[Cell::Real(c1.x),Cell::Real(c1.y),Cell::Real(c2.x),Cell::Real(c2.y),Cell::Real(to.x),Cell::Real(to.y)])?,PathSegment::QuadTo{c,to}=>p.insert_key_float("semio_drawing_quad",sid,&[Cell::Real(c.x),Cell::Real(c.y),Cell::Real(to.x),Cell::Real(to.y)])?,PathSegment::ArcTo{rx,ry,x_rotation,large_arc,sweep,to}=>p.insert_key_float("semio_drawing_arc",sid,&[Cell::Real(*rx),Cell::Real(*ry),Cell::Real(*x_rotation),Cell::Integer(i64::from(*large_arc)),Cell::Integer(i64::from(*sweep)),Cell::Real(to.x),Cell::Real(to.y)])?,PathSegment::Close=>p.insert_key_float("semio_drawing_close",sid,&[])?}}},
DrawNode::Text{value,at,style}=>p.insert_key_float("semio_drawing_text",id,&[Cell::Text(value),Cell::Real(at.x),Cell::Real(at.y),style_cell(style.as_deref(),styles)?])?,
DrawNode::Group{transform:t,children}=>{p.insert_key_float("semio_drawing_group",id,&[Cell::Real(t.translation.x),Cell::Real(t.translation.y),Cell::Real(t.translation.z),Cell::Real(t.rotation.x),Cell::Real(t.rotation.y),Cell::Real(t.rotation.z),Cell::Real(t.rotation.w),Cell::Real(t.scale.x),Cell::Real(t.scale.y),Cell::Real(t.scale.z)])?;p.check_rows(stack.len().checked_add(children.len()).ok_or("drawing traversal count overflow")?)?;for(ordinal,child)in children.iter().enumerate(){let kind=match child{DrawNode::Path{..}=>"path",DrawNode::Text{..}=>"text",DrawNode::Group{..}=>"group",DrawNode::Image{..}=>"image"};let cid=p.insert_float("semio_drawing_node",&[Cell::Text(kind)])?;p.insert_float("semio_drawing_child",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Integer(cid)])?;stack.push((cid,child));}},
DrawNode::Image{at,width,height,mime,bytes}=>p.insert_key_float("semio_drawing_image",id,&[Cell::Real(at.x),Cell::Real(at.y),Cell::Real(*width),Cell::Real(*height),Cell::Text(mime),Cell::Blob(bytes)])?}p.checkpoint()?;}Ok(root)}
fn style_name(row:SqliteRow<'_>,i:usize,names:&BTreeMap<i64,&str>,r:&mut Reconstruction<'_,'_>)->Result<Option<String>,String>{if row.is_null(i)?{Ok(None)}else{r.text(names.get(&row.integer(i)?).ok_or_else(||String::from("dangling drawing style"))?).map(Some)}}
impl ArtifactSqliteSnapshot for SemioDrawingSnapshot{
fn retire_sqlite_snapshot(self){drop(crate::standards::v1::subsets::base::schema::snapshot::native_decoding::Owned::new(self));}

fn encode_sqlite_snapshot_native(&self,encoding:store::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,String>{super::native_encoding::encode(self,encoding,control)}
fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{super::native_decoding::decode(payload,control)}
fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=Bound::new("",control)?;self.native_fields(&mut b)?;b.finish()}

fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;
if dialect.artifact_kind!="s.stdio.semio"||dialect.standard!="v1"||(dialect.subset!="*"&&dialect.subset!="drawing"){return Err(String::from("Semio owned snapshot dialect differs from its dedicated semantic subset").into());}
let row=database.table("semio_drawing_document")?.single_row()?;
if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(String::from("Semio owned document identity differs from projected semantic fields").into());}
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}

const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;let bg=colors(self.canvas.background);p.insert_key_float("semio_drawing_document",1,&[Cell::Text(&self.schema),Cell::Real(self.canvas.width),Cell::Real(self.canvas.height),bg[0],bg[1],bg[2],bg[3]])?;let mut styles=BTreeMap::new();for(ordinal,s)in self.styles.iter().enumerate(){let f=colors(s.fill);let k=colors(s.stroke);let id=p.insert_float("semio_drawing_style",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&s.name),f[0],f[1],f[2],f[3],k[0],k[1],k[2],k[3],s.stroke_width.map(Cell::Real).unwrap_or(Cell::Null),s.opacity.map(|v|Cell::Float32(v)).unwrap_or(Cell::Null)])?;if styles.insert(s.name.as_str(),id).is_some(){return Err("duplicate drawing style identity".into());}}let mut names=BTreeSet::new();for(ordinal,layer)in self.layers.iter().enumerate(){if !names.insert(layer.id.as_str()){return Err("duplicate drawing layer identity".into());}let root=project_node(&layer.root,&styles,&mut p)?;p.insert_float("semio_drawing_layer",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&layer.id),Cell::Text(&layer.name),Cell::Integer(i64::from(layer.visible)),Cell::Integer(root)])?;}p.finish()}
fn from_sqlite_database(db:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String> { Self::reconstruct_sqlite_database(db, control, Self::SQLITE_SCHEMA) }
}

impl SemioDrawingSnapshot {
    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(db:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,String> {
control.check_database(db,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(db,declared_schema,control.limits()).map_err(|e|e.to_string())?;let doc=single_float_row(db,"semio_drawing_document")?;identity(doc,8)?;if doc.rowid!=1{return Err("invalid drawing document identity".into());}let style_rows=ordered_float_rows(db,"semio_drawing_style",2,control)?;let layers=ordered_float_rows(db,"semio_drawing_layer",2,control)?;let mut styles=BTreeMap::new();let mut names=BTreeSet::new();for s in &style_rows{identity(s,14)?;if s.integer(1)?!=1||styles.insert(s.rowid,s.text(3)?).is_some()||!names.insert(s.text(3)?){return Err("invalid drawing style owner or identity".into());}}let mut roots=Vec::new();let mut names=BTreeSet::new();for layer in &layers{identity(layer,7)?;if layer.integer(1)?!=1||!names.insert(layer.text(3)?){return Err("invalid drawing layer owner or identity".into());}roots.push(layer.integer(6)?);}
let mut nodes=details(db,"semio_drawing_node",2,control)?;let mut paths=details(db,"semio_drawing_path",2,control)?;let mut texts=details(db,"semio_drawing_text",5,control)?;let mut groups_map=details(db,"semio_drawing_group",11,control)?;let mut images=details(db,"semio_drawing_image",7,control)?;let mut children=groups(db,"semio_drawing_child",4,&groups_map,control)?;let mut segments=groups(db,"semio_drawing_segment",4,&paths,control)?;let mut moves=details(db,"semio_drawing_move",3,control)?;let mut lines=details(db,"semio_drawing_line",3,control)?;let mut cubics=details(db,"semio_drawing_cubic",7,control)?;let mut quads=details(db,"semio_drawing_quad",5,control)?;let mut arcs=details(db,"semio_drawing_arc",8,control)?;let mut closes=details(db,"semio_drawing_close",1,control)?;
let mut seen=BTreeSet::new();let mut schedule=Vec::new();let mut stack:Vec<(i64,bool)>=roots.iter().rev().map(|id|(*id,false)).collect();while let Some((id,done))=stack.pop(){if done{schedule.push(id);continue;}if !nodes.contains_key(&id)||!seen.insert(id){return Err("cyclic multiply owned or dangling drawing node".into());}stack.push((id,true));for child in children.get(&id).into_iter().flatten(){stack.push((child.integer(3)?,false));}if seen.len()%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,seen.len(),0)?;}}if seen.len()!=nodes.len(){return Err("orphan drawing node".into());}let mut r=Reconstruction::new(control)?;let mut built=Owned::new(BTreeMap::new());for id in schedule{let row=nodes.remove(&id).ok_or("duplicate drawing ownership")?;let node=match row.text(1)?{
"path"=>{let p=paths.remove(&id).ok_or("missing drawing path fields")?;let mut native=Vec::new();for s in segments.remove(&id).unwrap_or_default(){let sid=s.rowid;native.push(match s.text(3)?{"move"=>PathSegment::MoveTo{to:point(moves.remove(&sid).ok_or("missing drawing move fields")?,1)?},"line"=>PathSegment::LineTo{to:point(lines.remove(&sid).ok_or("missing drawing line fields")?,1)?},"cubic"=>{let a=cubics.remove(&sid).ok_or("missing drawing cubic fields")?;PathSegment::CubicTo{c1:point(a,1)?,c2:point(a,3)?,to:point(a,5)?}},"quad"=>{let a=quads.remove(&sid).ok_or("missing drawing quad fields")?;PathSegment::QuadTo{c:point(a,1)?,to:point(a,3)?}},"arc"=>{let a=arcs.remove(&sid).ok_or("missing drawing arc fields")?;PathSegment::ArcTo{rx:a.real(1)?,ry:a.real(2)?,x_rotation:a.real(3)?,large_arc:boolean(a.integer(4)?)?,sweep:boolean(a.integer(5)?)?,to:point(a,6)?}},"close"=>{closes.remove(&sid).ok_or("missing drawing close fields")?;PathSegment::Close},_=>return Err("unknown drawing segment kind".into())});r.checkpoint()?;}DrawNode::Path{segments:native,style:style_name(p,1,&styles,&mut r)?}},
"text"=>{let a=texts.remove(&id).ok_or("missing drawing text fields")?;DrawNode::Text{value:r.text(a.text(1)?)?,at:point(a,2)?,style:style_name(a,4,&styles,&mut r)?}},
"group"=>{let a=groups_map.remove(&id).ok_or("missing drawing group fields")?;let mut native=Owned::new(Vec::new());for child in children.remove(&id).unwrap_or_default(){native.get_mut().push(built.get_mut().remove(&child.integer(3)?).ok_or("missing owned drawing child")?);}DrawNode::Group{transform:transform(a)?,children:native.take()}},
"image"=>{let a=images.remove(&id).ok_or("missing drawing image fields")?;DrawNode::Image{at:point(a,1)?,width:a.real(3)?,height:a.real(4)?,mime:r.text(a.text(5)?)?,bytes:r.blob(a.blob(6)?)?}},_=>return Err("unknown drawing node kind".into())};built.get_mut().insert(id,node);r.checkpoint()?;}
if !paths.is_empty()||!texts.is_empty()||!groups_map.is_empty()||!images.is_empty()||!children.is_empty()||!segments.is_empty()||!moves.is_empty()||!lines.is_empty()||!cubics.is_empty()||!quads.is_empty()||!arcs.is_empty()||!closes.is_empty(){return Err("orphan or contradictory drawing node or segment detail".into());}let mut native_styles=Vec::new();for s in style_rows{native_styles.push(DrawStyle{name:r.text(s.text(3)?)?,fill:rgba(s,4)?,stroke:rgba(s,8)?,stroke_width:optional_real(s,12)?,opacity:if s.is_null(13)?{None}else{Some(s.binary32(13)?)}});}let mut native_layers=Owned::new(Vec::new());for layer in layers{native_layers.get_mut().push(DrawLayer{id:r.text(layer.text(3)?)?,name:r.text(layer.text(4)?)?,visible:boolean(layer.integer(5)?)?,root:built.get_mut().remove(&layer.integer(6)?).ok_or("missing drawing layer root")?});}if !built.get_mut().is_empty(){return Err("orphan reconstructed drawing node".into());}let value=Owned::new(Self{schema:r.text(doc.text(1)?)?,canvas:DrawCanvas{width:doc.real(2)?,height:doc.real(3)?,background:rgba(doc,4)?},styles:native_styles,layers:native_layers.take()});r.checkpoint()?;Ok(value.take())
    }
}

fn float_columns(table:&str)->&'static [FloatColumn]{match table{"semio_drawing_document"=>&[FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary32(4),FloatColumn::Binary32(5),FloatColumn::Binary32(6),FloatColumn::Binary32(7)],"semio_drawing_style"=>&[FloatColumn::Binary32(4),FloatColumn::Binary32(5),FloatColumn::Binary32(6),FloatColumn::Binary32(7),FloatColumn::Binary32(8),FloatColumn::Binary32(9),FloatColumn::Binary32(10),FloatColumn::Binary32(11),FloatColumn::Binary64(12),FloatColumn::Binary32(13)],"semio_drawing_text"=>&[FloatColumn::Binary64(2),FloatColumn::Binary64(3)],"semio_drawing_group"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10)],"semio_drawing_image"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4)],"semio_drawing_move"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2)],"semio_drawing_line"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2)],"semio_drawing_cubic"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6)],"semio_drawing_quad"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4)],"semio_drawing_arc"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(6),FloatColumn::Binary64(7)],_=>&[]}}
trait FloatProjection { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>; fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>; }
impl FloatProjection for Projection<'_,'_> { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>{insert_ieee754(self,table,cells,float_columns(table))} fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>{insert_key_ieee754(self,table,key,cells,float_columns(table))} }
fn float_rows<'a>(db:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let table_rows=db.table(table)?;control.check_rows(table_rows.rows.len())?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,table_rows.rows.len())?;let mut result=Vec::new();for(count,row)in table_rows.rows.iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,table_rows.rows.len())?;}}Ok(result)}
fn ordered_float_rows<'a>(db:&'a SqliteDatabase,table:&str,ordinal:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let mut result=Vec::new();for(count,row)in semio_framework_os_kernel::sqlite_snapshot::artifact::ordered_row_refs(db.table(table)?,ordinal,control)?.into_iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn single_float_row<'a>(db:&'a SqliteDatabase,table:&str)->Result<SqliteRow<'a>,String>{SqliteRow::new(db.table(table)?.single_row()?,float_columns(table))}

impl SemioDrawingSnapshot{
/// 📏️ Bounds explicitly owned native fields before encoding.
pub fn native_fields(&self,b:&mut Bound<'_,'_>)->Result<(),String>{b.text(&self.schema)?;b.scalars(6)?;b.entities(self.styles.len())?;for style in &self.styles{b.text(&style.name)?;b.scalars(10)?;}b.entities(self.layers.len())?;for layer in &self.layers{b.text(&layer.id)?;b.text(&layer.name)?;b.scalars(1)?;native_draw_nodes(std::slice::from_ref(&layer.root),b)?;}Ok(())}
}

fn native_draw_nodes(roots:&[DrawNode],b:&mut Bound<'_, '_>)->Result<(),String>{b.entities(roots.len())?;let mut pending:Vec<_>=roots.iter().rev().collect();while let Some(node)=pending.pop(){b.entities(1)?;match node{DrawNode::Path{segments,style}=>{b.optional_text(style.as_deref())?;b.entities(segments.len())?;for segment in segments{b.scalars(match segment{PathSegment::MoveTo{..}|PathSegment::LineTo{..}=>2,PathSegment::CubicTo{..}=>6,PathSegment::QuadTo{..}=>4,PathSegment::ArcTo{..}=>7,PathSegment::Close=>0})?;}},DrawNode::Text{value,style,..}=>{b.text(value)?;b.optional_text(style.as_deref())?;b.scalars(2)?;},DrawNode::Group{children,..}=>{b.scalars(10)?;b.entities(children.len())?;pending.extend(children.iter().rev());},DrawNode::Image{mime,bytes,..}=>{b.scalars(4)?;b.text(mime)?;b.bytes(bytes)?;}}}Ok(())}
